code_sketch:
order.schema.json  (v1.2, owner: domain steering group, compat: additive-only)

bindings = codegen(order.schema)     # or hand-written codec + conformance fixtures

def publish(order: Order) -> Payload:      # translator, egress
    return to_language(order, bindings)

def receive(payload) -> Order:             # translator, ingress
    errors = validate(payload, order.schema)
    if errors:
        raise InvalidMessage(errors)       # dead-letter / invalid-message channel
    return from_language(bindings.decode(payload))
